          items, matched, answer, holdDurationMs, timingBonus,
          matchedDrive: matchedOpt?.drive ?? null,
          matchedPolarity: matchedOpt?.polarity ?? 'neutral',
          correctnessScore: matchedOpt?.correctnessScore ?? 0.5,
        },
        durationMs,
      };
    },
  };
