+          response_time: durationMs < 30000 ? 0.7 : 0.5,
+        },
+        Somatic: {
+          accuracy: baseAccuracy,
+          response_time: durationMs < 5000 ? 0.9 : durationMs < 15000 ? 0.7 : 0.5,
+          consistency: baseAccuracy,
+        },
